const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const seattle = ee.Geometry.Point([-122.3321, 47.6062]);
    const dataset = 'UCSB-CHG/CHIRPS/DAILY';
    const band = 'precipitation';

    const years = [2021, 2020, 2019];
    const results = {};

    for (const year of years) {
        const startDate = ee.Date.fromYMD(year, 9, 1);
        const endDate = ee.Date.fromYMD(year, 11, 30);

        // 2. Data Acquisition & Check
        const collection = ee.ImageCollection(dataset)
            .filterBounds(seattle)
            .filterDate(startDate, endDate.advance(1, 'day')); // a day is added to make the range inclusive

        const collectionSize = collection.size().getInfo();
        if (collectionSize === 0) {
            console.log(`No images found for ${year}.`);
            console.log("C1");
            return;
        }

        // 3. Processing
        const totalPrecipitationImage = collection.select(band).sum();

        // 4. Calculation
        const stats = totalPrecipitationImage.reduceRegion({
            reducer: ee.Reducer.mean(), // For a point, mean is equivalent to getting the pixel value
            geometry: seattle,
            scale: 5000,
            maxPixels: 1e9
        });

        const rainfall = stats.get(band).getInfo();

        // 5. Validation
        if (rainfall === null) {
            console.log(`Rainfall calculation failed for ${year}.`);
            console.log("C3");
            return;
        }

        results[year] = rainfall;
        console.log(`Total Rainfall ${year} (Sep-Nov): ${rainfall.toFixed(2)} mm`);
    }

    // Final Comparison
    const rainfall2021 = results[2021];
    const rainfall2020 = results[2020];
    const rainfall2019 = results[2019];

    if (rainfall2021 > rainfall2020 && rainfall2021 > rainfall2019) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('Authentication or Initialization failed:');
        console.error(e);
        console.log("D");
    }
}

initEE();
